import { searchCharacters, getCharacterById } from './BangumiRequest.js';
import React, { useState, useRef, useEffect, useCallback } from 'react';
import debounce from 'lodash.debounce';
import styles from './styles/InputStyles.module.css';

function GuessingCharacter() {
    const [inputTerm, setInputTerm] = useState('');
    const [results, setResults] = useState([]);
    const [isLoading, setIsLoading] = useState(false);
    const [isOpen, setIsOpen] = useState(false);
    const dropdownRef = useRef(null);

    // 使用useCallback确保debounce函数稳定
    const debouncedSearch = debounce(async (searchTerm) => {
        if (!searchTerm) {
            setResults([]);
            setIsOpen(false);
            return;
        }

        setIsLoading(true);
        setIsOpen(true);

        // 使用.then()处理异步结果
        searchCharacters(searchTerm)
            .then(response => {
                // 确保response是数组
                const newResults = Array.isArray(response) ? response : [];
                setResults(newResults);
                console.log("Search response:", typeof response);
                console.log("Search results:", newResults);
            })
            .catch(error => {
                console.error("Error fetching characters:", error);
                setResults([]);
            })
            .finally(() => {
                setIsLoading(false);
            });
    }, 300);

    // 点击外部关闭下拉框
    useEffect(() => {
        const handleClickOutside = (event) => {
            if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, []);

    // 处理搜索按钮点击
    const handleClick = () => {
        console.log("Button clicked:", inputTerm);
        debouncedSearch(inputTerm);
    };

    // 处理选择角色 - 使用.then()语法
    const handleSelect = (item) => {
        setIsLoading(true);

        getCharacterById(item.id)
            .then(response => {
                console.log('Selected character:', response);
                setResults([]);
                setIsOpen(false);
                setInputTerm(item.name);
            })
            .catch(error => {
                console.error("Error fetching character details:", error);
            })
            .finally(() => {
                setIsLoading(false);
            });
    };

    // 处理输入变化
    const handleInputChange = (e) => {
        const value = e.target.value;
        setInputTerm(value);
        // 如果输入为空，立即清除结果
        if (!value) {
            setResults([]);
            setIsOpen(false);
        }
    };

    return (
        <div className="App">
            <div>
                <h1>猜人物</h1>
            </div>
            <div className="search-dropdown" ref={dropdownRef}>
                <input
                    type="text"
                    value={inputTerm}
                    onChange={handleInputChange}
                    onKeyDown={(e) => e.key === 'Enter' && handleClick()}
                    placeholder="输入角色名..."
                    className={styles.standardInput}
                />
                <button
                    className={styles.buttonstyle}
                    onClick={handleClick}
                    disabled={isLoading || !inputTerm.trim()}
                >
                    {isLoading ? '搜索中...' : '搜索'}
                </button>
            </div>
            {isOpen && (
                <div className={styles.largeTextarea}>
                    {isLoading ? (
                        <div className={styles.standardInput}>搜索中...</div>
                    ) : results.length > 0 ? (
                        results.map(item => (
                            <div
                                key={item.id}
                                onClick={() => handleSelect(item)}
                                className={styles.standardInput}
                                style={{ cursor: 'pointer' }}
                            >
                                {item.name}
                            </div>
                        ))
                    ) : (
                        <div className={styles.standardInput}>未找到结果</div>
                    )}
                </div>
            )}
        </div>
    );
}

export default GuessingCharacter;
